    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_lists_newest_order_first(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert [o["order_id"] for o in orders] == [second, first]


def test_order_history_entries_have_order_id_status_and_total(shop):
    oid = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    entries = shop.insights.handle_order_history("c1").body["orders"]
    assert entries == [{"order_id": oid, "status": "placed", "total_cents": 2500}]


def test_order_history_total_includes_discount(shop):
    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    summary_total = shop.orders.handle_get(oid).body["total_cents"]
    entries = shop.insights.handle_order_history("c2").body["orders"]
    assert entries[0]["total_cents"] == summary_total == 10200


def test_order_history_includes_cancelled_orders_with_their_status(shop):
    oid = order(shop, "c1", ("PEN", 3)).body["order_id"]
    shop.orders.handle_cancel(oid)
    entries = shop.insights.handle_order_history("c1").body["orders"]
    assert entries == [{"order_id": oid, "status": "cancelled", "total_cents": 900}]


def test_order_history_only_includes_the_requested_customers_orders(shop):
    order(shop, "c2", ("PEN", 1))
    oid = order(shop, "c1", ("PEN", 1)).body["order_id"]
    entries = shop.insights.handle_order_history("c1").body["orders"]
